class SearchTree:
    def __init__(self, values):
        self.root = None
        for value in values:
            self.insert(value)

    def insert(self, key):
        def put(node):
            if node is None:
                return {"key": key, "left": None, "right": None}
            if key < node["key"]:
                node["left"] = put(node["left"])
            elif key > node["key"]:
                node["right"] = put(node["right"])
            return node
        self.root = put(self.root)

    def search_path(self, key):
        node, path = self.root, []
        while node is not None:
            path.append(node["key"])
            if key == node["key"]:
                break
            node = node["left"] if key < node["key"] else node["right"]
        return path

    def contains(self, key):
        path = self.search_path(key)
        return bool(path) and path[-1] == key

    def delete(self, key):
        def remove(node, target):
            if node is None:
                return None
            if target < node["key"]:
                node["left"] = remove(node["left"], target)
            elif target > node["key"]:
                node["right"] = remove(node["right"], target)
            else:
                if node["left"] is None:
                    return node["right"]
                if node["right"] is None:
                    return node["left"]
                successor = node["right"]
                while successor["left"] is not None:
                    successor = successor["left"]
                # 用後繼值替換，再從右子樹刪掉那個值，並接回結果
                pass
            return node
        self.root = remove(self.root, key)

    def inorder(self):
        result = []
        def visit(node):
            if node is None:
                return
            visit(node["left"])
            result.append(node["key"])
            visit(node["right"])
        visit(self.root)
        return result

