import math

class SearchLimit(Exception):
    pass

class Board:
    def __init__(self, grid, limit):
        self.grid = [row[:] for row in grid]
        self.n = len(grid)
        self.box = math.isqrt(self.n)
        self.limit = limit
        self.tried = 0

    def groups(self):
        yield from self.grid
        for c in range(self.n):
            yield [self.grid[r][c] for r in range(self.n)]
        for top in range(0,self.n,self.box):
            for left in range(0,self.n,self.box):
                yield [self.grid[r][c] for r in range(top,top+self.box)
                       for c in range(left,left+self.box)]

    def valid_givens(self):
        return all(len(values) == len(set(values))
                   for group in self.groups()
                   for values in [[x for x in group if x != 0]])

    def allowed(self,r,c,value):
        if value in self.grid[r] or any(self.grid[i][c]==value for i in range(self.n)):
            return False
        top,left = r//self.box*self.box, c//self.box*self.box
        return all(self.grid[i][j]!=value for i in range(top,top+self.box)
                   for j in range(left,left+self.box))

    def search(self):
        empty = next(((r,c) for r in range(self.n) for c in range(self.n)
                      if self.grid[r][c]==0),None)
        if empty is None:
            return True
        r,c = empty
        for value in range(1,self.n+1):
            if self.allowed(r,c,value):
                if self.tried >= self.limit:
                    raise SearchLimit()
                self.tried += 1
                self.grid[r][c] = value
                # 往下搜尋；成功則回True，失敗要把本格撤回0
                pass
        return False

def solve_board(grid, limit=10000):
    invalid = {"status":"invalid", "board":None}
    if type(grid) is not list or len(grid) not in (4,9):
        return invalid
    n = len(grid)
    if any(type(row) is not list or len(row)!=n for row in grid):
        return invalid
    if any(type(x) is not int or not 0<=x<=n for row in grid for x in row):
        return invalid
    if type(limit) is not int or not 0<=limit<=10000:
        return invalid
    board = Board(grid,limit)
    if not board.valid_givens():
        return invalid
    try:
        if board.search():
            return {"status":"solved", "board":board.grid}
        return {"status":"unsolved", "board":None}
    except SearchLimit:
        return {"status":"limit", "board":None}

